# Generated by secure-by-design v0.1.0 for OWASP-aligned security headers.
# Maps to: ISO 27001 A.8.26 / A.8.28, NIST SSDF PW.9.
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/security_headers.md

from __future__ import annotations

from collections.abc import Sequence

from starlette.datastructures import MutableHeaders
from starlette.types import ASGIApp, Message, Receive, Scope, Send


class SecurityHeadersMiddleware:
    """
    Plain ASGI middleware, so it leaves streaming responses alone.

      app.add_middleware(SecurityHeadersMiddleware)

    enable_strict_csp: set False in dev if a stricter CSP breaks hot reload. FastAPI's
      /docs page loads from a CDN, so it also needs False or a CSP of your own.
    allowed_frame_ancestors: set if you serve embeddable widgets and need a specific frame ancestor.
    additional_connect_src: domains your app legitimately fetches from (CSP connect-src additions).
    """

    def __init__(
        self,
        app: ASGIApp,
        *,
        enable_strict_csp: bool = True,
        allowed_frame_ancestors: Sequence[str] = (),
        additional_connect_src: Sequence[str] = (),
    ) -> None:
        self.app = app
        connect_src = ' '.join(["'self'", *additional_connect_src])
        frame_ancestors = ' '.join(allowed_frame_ancestors) or "'none'"

        self.headers = {
            'X-Content-Type-Options': 'nosniff',
            'X-Frame-Options': 'DENY' if frame_ancestors == "'none'" else 'SAMEORIGIN',
            'Referrer-Policy': 'strict-origin-when-cross-origin',
            'Permissions-Policy': 'geolocation=(), microphone=(), camera=()',
            'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
            'Cross-Origin-Opener-Policy': 'same-origin',
            'Cross-Origin-Resource-Policy': 'same-origin',
        }
        if enable_strict_csp:
            self.headers['Content-Security-Policy'] = '; '.join([
                "default-src 'self'",
                f'connect-src {connect_src}',
                "img-src 'self' data:",
                "style-src 'self' 'unsafe-inline'",  # tighten in your CSP review
                "script-src 'self'",
                "object-src 'none'",
                "base-uri 'self'",
                "form-action 'self'",
                f'frame-ancestors {frame_ancestors}',
                'upgrade-insecure-requests',
            ])

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope['type'] != 'http':
            await self.app(scope, receive, send)
            return

        async def send_with_headers(message: Message) -> None:
            if message['type'] == 'http.response.start':
                headers = MutableHeaders(scope=message)
                for name, value in self.headers.items():
                    headers[name] = value
                # Do NOT set Server — run uvicorn with --no-server-header.
            await send(message)

        await self.app(scope, receive, send_with_headers)
